@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {}

class BusinessUser {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + title : string
}

class Track {
  + trackNumber : int
}

class Suggestion {
  + similarityScore : float
}

Song --|> Single
Song --|> Hit

Artist "1" -- "*" Song : creates

User "1" -- "0..*" RegularUser
User "1" -- "0..*" BusinessUser

BusinessUser "1" -- "*" Song : uploads

RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : buys

Album "1" *-- "1..*" Track
Track "1" -- "1" Hit

RegularUser "1" -- "*" Suggestion
RegularUser "1" -- "*" Suggestion : receives

@enduml

